def split_amount(total_cents: int, n: int) -> list[int]:
    if n <= 0:
        raise ValueError("Number of parts 'n' must be a positive integer.")

    base = total_cents // n
    remainder = total_cents % n

    # Create a list with 'remainder' elements of 'base + 1' and 'n - remainder' elements of 'base'
    return [base + 1] * remainder + [base] * (n - remainder)
